"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[371],{2049:(e,t,a)=>{a.d(t,{Gi:()=>n,ZE:()=>r,gn:()=>i});let n="inline-flex min-w-[140px] items-center justify-center rounded-md border border-gray-300 bg-white px-4 py-2 text-sm text-gray-700 no-underline transition-colors hover:bg-gray-50 hover:border-gray-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gray-400 disabled:cursor-not-allowed disabled:opacity-60 disabled:hover:bg-white disabled:hover:border-gray-300",r=[{id:"mirror",name:"Mirror",icon:"/images/MirrorMirror-logo-1024.png",description:"Mirror, mirror in the hand. Who is the fairest of them all?",created:"2025-05",released:!1,appStore:"https://apps.apple.com/app/id6747995444"},{id:"owlguard-ai",name:"Owl Guard AI",icon:"/images/OwlGuardAI-logo-1024.png",description:"A little peace of mind for their digital world.",created:"2024-12",released:!1,appStore:null},{id:"prices-nearby",name:"Prices Nearby",icon:"/images/PricesNearby-logo-transparent.png",description:"Good Price, Nearby",created:"2026-09",released:!1,appStore:null},{id:"final-curtain",name:"Final Curtain",icon:"/images/previews/FinalCurtain-curtain-A.png",description:"Time is finite. What matters can endure.",created:"2025-08",released:!1,appStore:null},{id:"learner-coin",name:"Learner Coin",icon:"/images/LearnerCoin-logo-transparent.png",description:"An investment in knowledge always pays the best interest.",created:"2025-08",attribution:"Benjamin Franklin — The Franklin Institute",released:!1,appStore:null},{id:"translate-talkie",name:"Translate Talkie",icon:"/images/TranslateTalkie-logo-1024.png",description:"Two phones. Two languages. One conversation.",created:"2026-01",released:!1,appStore:null,listed:!1},{id:"understone",name:"Understone",icon:"/images/Understone-logo-transparent.png",description:"Beneath ancient strata, the dwarven annals begin.",created:"2025-10",released:!1,appStore:null},{id:"epocharium",name:"Epocharium",icon:"/images/Epocharium-logo-transparent.png",description:"Civilizations in dialogue. Time in perspective.",created:"2026-10",released:!1,appStore:null}],i=r.filter(e=>!1!==e.listed).sort((e,t)=>e.name.localeCompare(t.name,"en"))},6627:(e,t,a)=>{a.d(t,{bK:()=>l,mD:()=>u,XL:()=>m,JZ:()=>h});var n=a(4089),r=a(7995);let i=JSON.parse('{"title":"Final Curtain Support","updated":"Last updated: October 11, 2026","sections":[{"title":"Your time horizon","paragraphs":["Set a birth date and a horizon for reflection, then explore recurring activities, large time blocks, reserves and independent profiles. These are assumptions you control, not a predicted lifespan."]},{"title":"Lists, profiles and summaries","paragraphs":["Edit activities and amounts in the planner. A full swipe deletes an activity immediately; clearing a list or deleting a profile asks for confirmation. At least one profile remains. Summaries use an on-device model when available. If generation is unavailable or fails, the app shows a status message and may keep an earlier summary."]},{"title":"Pro, purchases and local data","paragraphs":["Final Curtain Pro is a one-time purchase that unlocks Compare Choices and the Home Screen widget. An eligible verified legacy widget purchase also unlocks Pro; you do not need to buy Pro again for that entitlement. Use Restore Purchases with the eligible Apple Account. If a product or price is unavailable, check your connection and retry rather than buying again to resolve an existing purchase. Apple displays the available offer and handles payment and refund requests.","After unlocking, add and configure the widget in iOS. Updates follow WidgetKit’s schedule. Profiles stay on this device; restoring a purchase does not recover deleted local planning data. TestFlight purchase tests use Apple’s sandbox and do not charge real money."]},{"title":"Contact support","paragraphs":["Email support@ideaspike.com with the app version, device model, operating-system version and a short description of the issue. During private testing you can also use TestFlight feedback. Do not send passwords, sign-in codes, payment details or private recordings."]}]}');var o=a(8526);let s=JSON.parse('{"support":{"title":"Owl Guard AI Support","sections":[{"title":"Getting started","paragraphs":["Open Owl Guard AI, start the eligible seven-day trial or annual subscription, or restore eligible existing access, then use Begin Recording and Apple’s broadcast confirmation. Recording never starts automatically. The current analysis models are included in the app; if a model cannot load, analysis remains unavailable until the app can load it."]},{"title":"Reviewing evidence","paragraphs":["Open Local Evidence beside Settings and authenticate with Face ID, Touch ID or the device passcode. Review retained screenshots, times, category results and sustained-event groups. The app saves selected screenshots, not a continuous recording. Do not send private screenshots to support."]},{"title":"Subscription, trial and restoration","paragraphs":["Where Apple offers an eligible introductory trial, the annual subscription begins with seven days free, then automatically renews at the localized annual price shown before purchase unless cancelled. Payment is charged to your Apple Account. Check the actual offer, price, currency and renewal period in Apple’s purchase sheet. Cancel at least 24 hours before the trial or current period ends to avoid renewal.","Use Apple’s subscription settings to manage or cancel. Use Restore Purchases when needed. Restoration does not restart an introductory offer. Cancellation leaves an already paid period available until its verified expiration; after expiry, new monitoring stops while retained evidence remains available under its retention rules. Apple handles refund requests, subject to eligibility and applicable law."]},{"title":"Beta alerts","paragraphs":["Enable Local alerts (Beta) in Settings to receive reminders for sustained detections. Check iOS notification settings and Focus if reminders do not appear. Owl Guard AI provides screening assistance; it does not block or close other apps."]},{"title":"Existing purchases","paragraphs":["Existing verified one-time full-access purchases remain recognized. Existing non-renewing seven-day trials keep their original deadlines and do not enroll you in a subscription. Any purchase sharing depends on the applicable Apple entitlement and eligibility; sharing access never shares evidence. Evidence stays separately on each device."]},{"title":"Managing storage","paragraphs":["In Settings, choose how long to keep recordings (30 days, 90 days or no time limit) and the recording storage limit (200 MB, 500 MB, 1 GB or 2 GB). The default is 30 days and 200 MB. The oldest records and their saved images are replaced when storage is full. Use Load more in the evidence library to view older entries. Delete All removes both pictures and score-only history after confirmation and device authentication."]},{"title":"Reporting an issue","paragraphs":["Provide the app version, device model, iOS version, access status and the action that failed. Contact support@ideaspike.com. Do not send passwords or private screenshots."]}]},"privacy":{"title":"Owl Guard AI Privacy Policy","sections":[{"title":"Screenshots stay on this device","paragraphs":["Owl Guard AI analyzes sampled screen images and text locally during a visible, user-authorized system broadcast. Selected screenshots and screening results are kept in the local evidence library on that device; the app does not send them to IDEASpike or a cloud AI provider. No Owl Guard AI registration is required."]},{"title":"Local storage and controls","paragraphs":["Recording history and saved images stay in protected storage and are excluded from backups. In Settings, choose a retention period (30 days by default, 90 days or no time limit) and a recording storage limit (200 MB by default, 500 MB, 1 GB or 2 GB). Expired records are removed on later access or a sample write. When the selected storage limit is reached, the oldest records and associated images are replaced. Reducing retention or storage asks for confirmation and device authentication. Delete All removes saved images and score-only history together."]},{"title":"Device authentication","paragraphs":["Face ID, Touch ID or the device passcode protects evidence viewing and deletion. The app receives an authentication result, not biometric templates."]},{"title":"Optional local alerts (Beta)","paragraphs":["Alerts are optional and off by default for new users. Notifications use generic text without evidence images or extracted text. Delivery may be missed or delayed. Evidence review works with alerts disabled."]},{"title":"Apple purchases","paragraphs":["Apple handles payments, subscriptions and purchase restoration. Owl Guard AI verifies transactions and renewal status on the device and stores local access status, trial timing and subscription expiry. Screen content is not sent with a purchase.","Where Apple offers an eligible seven-day introductory free trial, the annual subscription then automatically renews at the localized annual price unless cancelled. Manage or cancel through Apple’s subscription settings. Existing verified one-time full-access purchases and non-renewing trial deadlines remain recognized without automatic subscription enrollment. Sharing eligible access never shares evidence."]},{"title":"Data collection","paragraphs":["The current app has no advertising, tracking or third-party analytics SDK, and no developer-run screen-data upload service. Its screen-analysis models and text rules are included in the app and run on the device rather than sending screenshots to a cloud AI provider. App downloads and updates, purchases, and optional website or support interactions still use network services. Apple may process data for its own App Store and operating-system services under Apple policies."]},{"title":"Your private media","paragraphs":["The evidence library stores selected screenshots, capture times and screening results for the categories you enable. Screenshots can contain personal information from other apps. You control recording, monitored categories, retention and deletion. Expanding selected categories or storage scope asks for renewed confirmation in Settings."]},{"title":"Contact","paragraphs":["Contact support@ideaspike.com for support or privacy questions. Do not send private screenshots. IDEASpike cannot remotely inspect or delete the evidence kept only on your device; use the local controls. Applicable privacy rights remain available."]},{"title":"This website and support email","paragraphs":["These public pages are hosted on GitHub Pages. The hosting provider processes normal web requests, which can include an IP address and browser information. These pages do not use advertising or analytics tools. If you email support, we use the message and your email address to respond through our email provider. Do not include private screenshots, passwords or payment details. This optional website or email interaction is separate from the app’s local screenshot processing."]}]},"terms":{"title":"Owl Guard AI Terms of Use","sections":[{"title":"Authorized monitoring","paragraphs":["Use Owl Guard AI only on a device you are entitled to use, with lawful authority and any permission required by applicable law. Start recording through Apple’s visible broadcast confirmation. Use the app lawfully and respect other people’s privacy rights. Review the selected screening categories and storage choices before recording."]},{"title":"Analysis and alert limits","paragraphs":["The app samples selected screen content and runs local models and text rules. Results can be incomplete, wrong or delayed. Optional alerts do not block or close other apps and may be affected by iOS notification settings. Owl Guard AI provides screening assistance; review retained evidence in context and use appropriate supervision."]},{"title":"Local evidence","paragraphs":["Captured images can contain sensitive messages and information from other apps. Device authentication protects evidence viewing and deletion. You control capture, categories, retention and storage. Expiry, capacity replacement and deletion can permanently remove recordings. Access sharing does not share evidence between devices."]},{"title":"Subscriptions and legacy access","paragraphs":["Where offered, an annual auto-renewing subscription may include an eligible seven-day introductory trial. Apple shows the local price, bills your Apple Account and manages eligibility and cancellation. Cancel at least 24 hours before the trial or current period ends to avoid renewal; manage the subscription in Apple’s settings. Restoration does not restart a trial. Existing verified one-time full access and non-renewing trial deadlines remain valid without automatic subscription enrollment. After access expires, new monitoring stops; retained recordings follow their retention rules."]},{"title":"Licence and intellectual property","paragraphs":["For App Store downloads, Apple’s Standard EULA governs the app licence unless a custom EULA is provided for your country or region through App Store Connect. These Terms supplement the applicable EULA and govern IDEASpike accounts, online services, app content and paid entitlements, where offered. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the app for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design, models and supplied content."]},{"title":"Purchases and consumer rights","paragraphs":["Purchases, restoration and refund requests follow Apple’s processes and applicable law. TestFlight transactions use Apple’s sandbox and do not charge real money. These product-specific conditions do not remove mandatory consumer rights."]},{"title":"Availability and your rights","paragraphs":["IDEASpike may update, suspend or discontinue features. To the extent permitted by law, the app is provided as available without additional warranties beyond those expressly stated in these terms or required by law, and IDEASpike is not liable for indirect or consequential loss arising from screening results, missed or delayed alerts, or service interruption. Nothing in these terms excludes liability or consumer rights that cannot be excluded under applicable law. Updated terms appear here. Contact support@ideaspike.com for assistance."]}],"references":[{"label":"Apple Standard End User License Agreement","href":"https://www.apple.com/legal/internet-services/itunes/dev/stdeula/"}]},"updated":"Last updated: October 12, 2026"}'),p=JSON.parse('{"en":{"labels":{"updated":"Last updated: October 12, 2026","operator":"Operated by IDEASpike. Contact:"},"privacy":{"title":"Privacy Policy","body":"<h2>Your family data</h2><p>Learner Coin stores your parent email account, family name, member nicknames, tasks, notes, virtual balances, reward and activity history in its online service. Bank and investment features also store savings activity, simulated orders and positions, and related transaction records. AWS provides account authentication and storage. Use nicknames and include only information needed for family activities.</p>\\n<h2>Parent and child controls</h2><p>The parent account owns the family. Parent password protection is optional and can be enabled in Family. When enabled, parent controls lock after the configured access period, on switching to a child or when the app enters the background. Account deletion requires password verification. Parents should supervise family use and provide any permissions required by applicable law.</p>\\n<h2>Optional voice and AI processing</h2><p>OpenAI processes recordings for transcription and instructions to prepare drafts and interpret requested actions. Requests include relevant member references, visible task and reward drafts, Bank draft amounts, and simulated investment actions, instruments, amounts, quantities and visible positions. Review the visible draft or transaction confirmation before saving. Manual entry remains available. Provider processing may take place outside your country, including the United States.</p>\\n<h2>Provider use and recordings</h2><p>OpenAI processes AI requests under its API data controls, which describe provider use and retention. By default, API data is not used to train models; model-improvement sharing requires an explicit opt-in by the API customer. Include only information needed for the instruction. Device recordings are removed after successful transcription, cancellation or leaving the recording flow; Learner Coin does not keep the audio as a saved family record.</p>\\n<h2>Voice diagnostics and saved actions</h2><p>During this beta, Learner Coin keeps recognized and edited instructions, relevant drafts and action results for troubleshooting, scheduled for cleanup after seven days. Voice retry results remain available for one hour. Saved tasks, rewards, Bank and investment activity remain until removed through the available controls or account deletion. Operational diagnostics help run and troubleshoot the service; audio recordings are not stored in those records.</p>\\n<h2>Deleting your account and other requests</h2><p>In parent mode, open Family and choose Delete Account. The deletion flow removes the login account and associated active family, finance and voice records. A minimal account-closure record is kept to maintain the closed status. If the app reports that deletion is incomplete, retry or contact support@ideaspike.com. Deleting the app or signing out does not delete the online account. Contact the same address for access, correction or a privacy complaint; we may verify that you control the account.</p>\\n<h2>Website and Apple services</h2><p>Opening a website or reference link sends ordinary web-request information, such as an IP address and browser information, to its hosting provider. Apple operates the App Store, TestFlight and device services under its own policies; feedback you choose to send through TestFlight may be visible to IDEASpike. Information you send to support is used to respond to your request. Do not send passwords, payment details or unnecessary personal information.</p>\\n<h2>Support and policy updates</h2><p>You may contact support@ideaspike.com or send beta feedback through TestFlight. Include only information needed to investigate the issue, without passwords, verification codes or unnecessary information about children. We will update this policy when relevant data practices change.</p>"},"terms":{"title":"Terms of Use","body":"<h2>Family tasks and rewards</h2><p>Learner Coin helps families organize tasks, approvals, rewards and learning activities. Parents are responsible for setting appropriate tasks and fulfilling any real-world reward promises they make. The service does not guarantee a child’s learning, behaviour or financial outcome.</p>\\n<h2>Virtual finance and investment learning</h2><p>The current app includes Bank and savings ledgers and simulated investment orders and positions. Coins, Bank balances, deposits, withdrawals, interest, borrowing, fees and trades shown in these features are family learning records or simulations. They do not open a real bank or brokerage account, transfer or safeguard real money, purchase securities, provide deposit insurance or create a right to redeem value from IDEASpike. Any actual exchange or reward arranged within a family occurs outside these app ledgers.</p>\\n<h2>Reference information and decisions</h2><p>Reference prices, rates and other market information may be delayed, unavailable, incomplete or wrong. Simulated execution, returns and borrowing terms can differ materially from real markets. The app does not provide personalized investment, financial, tax or legal advice. Review amounts, instruments and the displayed preview before confirming an operation. Keep independent records of any real-world family arrangements.</p>\\n<h2>Accounts, children and AI</h2><p>Use only accounts and family profiles you are authorized to access. Parents should supervise children’s use, protect account access and provide the permissions required by applicable law. Submit voice or text to the AI feature only when you have the required permission for that information. AI may misunderstand instructions or produce incorrect drafts. Voice instructions prepare or navigate visible forms; review and confirm the relevant save or simulated transaction yourself.</p>\\n<h2>Licence and intellectual property</h2><p>For App Store downloads, Apple’s Standard EULA governs the app licence unless a custom EULA is provided for your country or region through App Store Connect. These Terms supplement the applicable EULA and govern IDEASpike accounts, online services, app content and paid entitlements, where offered. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the app for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design and supplied content. You retain rights in content you provide and permit IDEASpike and its processors to process it for the features and optional data uses you choose, as described in the Privacy Policy.</p>\\n<h2>Responsible use</h2><p>Use the app lawfully. Do not submit unlawful or infringing content, attempt to access another family’s records or disrupt the service.</p>\\n<h2>Availability and your rights</h2><p>IDEASpike may update, suspend or discontinue features. To the extent permitted by law, the app and online service are provided as available without additional warranties beyond those expressly stated in these terms or required by law, and IDEASpike is not liable for indirect or consequential loss arising from family arrangements, simulated financial results, AI drafts or service interruption. Nothing in these terms excludes liability or consumer rights that cannot be excluded under applicable law. Updated terms appear here. Contact support@ideaspike.com for assistance.</p>"},"support":{"title":"Support","body":"<h2>Family, tasks and rewards</h2><p>Sign in to the parent account, create your family and use child nicknames. Add tasks and rewards, review submissions and confirm actions in the appropriate parent or child profile. Enable parent password protection in Family when you need the additional access control.</p>\\n<h2>Bank and investment ledgers</h2><p>Bank, savings, activity, orders and positions are implemented learning features. They record virtual amounts and simulated investments rather than moving real money. Use the displayed preview and confirm the amount, instrument and selected child before saving. If a reference price is unavailable or an operation is pending, use the status or retry controls and check activity before submitting another operation.</p>\\n<h2>Voice drafts and saves</h2><p>You can type manually or use the optional OpenAI voice flow. Review the AI-sharing notice before using it. Recording or typing an instruction may transmit the information, visible drafts and simulated investment context described in the Privacy Policy. AI does not replace your review: use the visible confirmation to save tasks, rewards or simulated financial actions. If interpretation fails, edit the instruction or use manual controls.</p>\\n<h2>Account deletion and privacy</h2><p>In parent mode, open Family and choose Delete Account, then complete password verification. If the app reports that deletion is incomplete, retry or contact support@ideaspike.com. Removing the app or signing out alone does not remove cloud family records.</p>\\n<h2>Contact support</h2><p>Email support@ideaspike.com with the app version, device, operating-system version and a short description, or use TestFlight feedback during testing. Describe the type of failed operation without sending passwords, verification codes, payment details, private recordings or unnecessary information about children.</p>"}}}'),d=JSON.parse('{"en":{"labels":{"updated":"Last updated: October 10, 2026","operator":"Operated by IDEASpike. Contact:"},"privacy":{"title":"Privacy Policy","body":"<h2>A two-device voice pilot</h2><p>Translate Talkie pairs two devices in a configured room for short translated voice messages. No separate personal account is required. A randomly generated device identifier and chosen language are saved on the device and sent to the room service. That identifier is not proof of the speaker’s identity.</p>\\n<h2>Audio, text and recipients</h2><p>Microphone permission lets the app record while you hold the talk control. The recording is uploaded to the AWS-hosted service. OpenAI processes audio for transcription, text for translation and translated text for synthesized speech. The other paired device receives message text and translated audio. Request/room identifiers, timestamps and processing errors support delivery and troubleshooting. Do not record bystanders or share another person’s speech without the necessary permission.</p>\\n<h2>Retention and local storage</h2><p>The service’s room-message events, including translated text and audio, are configured to expire after about five minutes. Database expiration is asynchronous and may take longer. The current app keeps the visible conversation in memory during the running session; its device identifier and language preference persist locally. Temporary recording files are normally removed after the app reads the recording; interrupted or very short recordings may remain until later cleanup. Provider processing and operational logs are separate from room expiry, and copies held by a recipient are outside our control.</p>\\n<h2>Providers and your choices</h2><p>AWS hosts room state and message delivery. OpenAI’s separate processing, retention and data-use settings apply to the transcription, translation and speech services. Processing may occur outside your country, including the United States. You can deny microphone permission or stop recording and leave the app. This pilot does not authenticate the other speaker or provide private enterprise rooms; confirm who is paired and avoid confidential information. Contact support for room/device-data assistance.</p>\\n<h2>Website, Apple services and support</h2><p>Opening a website or reference link sends ordinary web-request information, such as an IP address and browser information, to its hosting provider. Apple operates the App Store, TestFlight and device services under its own policies; feedback you choose to send through TestFlight may be visible to the developer. If you email support, we use your email address and message to respond. Do not send passwords, payment details or unnecessary personal information.</p>\\n<h2>Changes and privacy assistance</h2><p>This policy applies to this application. We update it when its processing changes. Contact support@ideaspike.com for privacy questions, access, correction or deletion assistance. Applicable privacy rights remain available. Retained support correspondence may be needed to handle your request or meet legal obligations.</p>\\n<h2>AI provider policy</h2><p>See <a href=\\"https://developers.openai.com/api/docs/guides/your-data\\">OpenAI API data controls</a> for provider processing, retention and data-sharing settings. Room expiry or deletion from our service does not control a provider’s separate records.</p>"},"terms":{"title":"Terms of Use","body":"<h2>Controlled conversations</h2><p>Use this pre-release tool for short, supervised conversations between the two intended participants. Make sure each speaker understands that audio is uploaded for AI processing and that the other device receives the result. Do not record others without the permissions required in your circumstances.</p>\\n<h2>Translation limits</h2><p>This is recorded voice messaging, not continuous simultaneous interpretation. Transcription, translation and synthesized speech may omit words, change meaning or identify the wrong language. Check important meanings with the other participant. Do not rely on it for medical, legal, emergency, financial or confidential decisions.</p>\\n<h2>Room access and conduct</h2><p>The current demo room does not verify participant identity. Automatic pairing is not a security guarantee. Do not impersonate speakers, submit unlawful or abusive recordings, or interfere with another conversation. A venue’s operator is responsible for appropriately explaining and supervising its pilot use.</p>\\n<h2>Testing and continuity</h2><p>Network or provider failures can prevent delivery. Conversations are not a durable history service, and messages or room state may expire or reset. This pilot does not offer payments or subscriptions. Keep any needed record independently and with appropriate permission.</p>\\n<h2>Availability and your rights</h2><p>Features may change and depend on compatible devices, connectivity and third-party services where used. Pre-release testing may be interrupted or reset; keep any information you need independently. Nothing in these terms excludes rights or responsibilities that cannot be excluded under applicable law. Updated terms appear here. Contact support@ideaspike.com for assistance.</p>"},"support":{"title":"Translate Talkie Support","body":"<h2>Pair and talk</h2><p>Open the configured pilot app on two phones and wait for the paired status. Choose each phone’s language, hold the talk control to record, then release to send. Tap an incoming bubble to play its translated voice.</p>\\n<h2>Troubleshoot a pilot</h2><p>Check microphone permission, network access and the paired-room status. The current demo room supports two devices; an unintended active device can prevent the expected pairing. Check the selected language and keep recordings short. The conversation is not preserved as a permanent history.</p>\\n<h2>Contact support</h2><p>Email support@ideaspike.com with the app version, device model, operating-system version and a short description of the issue. During private testing you can also use TestFlight feedback. Do not send passwords, sign-in codes, payment details or private recordings.</p>"}}}'),c={mirror:n,"prices-nearby":o,"learner-coin":p,"translate-talkie":d,understone:JSON.parse('{"en":{"labels":{"updated":"Last updated: October 12, 2026","operator":"Understone by IDEASpike. Contact:"},"privacy":{"title":"Privacy Policy","body":"<h2>The app and your data</h2><p>Understone is a mineral-deduction game. It does not require an app account. We do not collect or send your gameplay, progress, local scores or sound settings to IDEASpike servers, and we do not use advertising, tracking or third-party analytics in the app.</p>\\n<h2>Information on your device</h2><p>The app saves your current expedition, discovered specimens, completed local scores and sound settings in its local storage. New Game replaces the current expedition but retains completed scores and sound settings. Deleting the app removes its local app data; copies may remain in device backups managed by Apple. The app does not operate cross-device synchronization. IDEASpike cannot remotely recover or delete these local files or your device backups; backup availability and restoration depend on your Apple/device settings.</p>\\n<h2>Apple purchases</h2><p>Apple processes the one-time full-expedition purchase. The app receives product, storefront and verified transaction information from StoreKit to display the local price, check your unlock and restore it. We do not receive your payment-card details or Apple Account password, and the app does not send transaction information to an IDEASpike server. Apple’s own privacy terms govern its purchase processing.</p>\\n<h2>Optional external links</h2><p>Geological research, music credits, support and privacy links open external pages only when you choose them. Those websites and your browser may process information under their own privacy policies. The app does not automatically upload your expedition when opening a link.</p>\\n<h2>Your choices and questions</h2><p>You can play the opening district without making a purchase, adjust sound settings, replace the current expedition or remove the app. Purchases and refunds are managed through Apple. Email support@ideaspike.com for privacy questions; any information you choose to send in a support email is used to respond to your request. Do not include passwords or payment-card details. Applicable privacy rights remain available.</p>\\n<h2>Policy updates</h2><p>This policy describes the current release. We will update it if the app’s data practices change.</p>"},"support":{"title":"App Support","body":"<h2>Plan each dig</h2><p>Tap an unexplored cell to reveal it. Opening a gem spends its mining cost immediately. Tap the mined gem again to collect it for free and earn XP. Empty cells and clue numbers are free; a clue adds the mining costs in its eight neighboring cells. Red warning marks count neighboring lethal mines.</p>\\n<h2>Recover stamina and keep exploring</h2><p>Stamina may reach zero. Eat a revealed hamburger when you need a full refill, or upgrade manually after earning enough XP. Restarting a failed floor creates a fresh map and restores that floor’s entry state. The interactive practice tutorial is available when starting a new game and from the in-game help page.</p>\\n<h2>Free opening and full expedition</h2><p>The opening district has three free floors and a camp shop. Leaving that first camp opens the one-time Unlock all field sites purchase. The full campaign spans eight districts and 24 floors; the one-time unlock opens the remaining field sites, with no subscription. Apple displays the price in your App Store currency. Camp items use earned game coins, not real money.</p>\\n<h2>Purchase and restore help</h2><p>Purchases are processed by Apple. Use Restore purchases on the unlock page with the eligible Apple Account. Restoration verifies full-game access; it does not restore a deleted expedition. A pending purchase unlocks only after a valid Apple transaction is verified; canceling preserves your progress. Review a changed price or currency before confirming a new offer. If prices or purchases are unavailable, check your connection, retry, and contact us if the issue continues. Do not buy again to resolve an existing purchase. Apple refund requests are handled at reportaproblem.apple.com, subject to eligibility and applicable law.</p>\\n<h2>Progress and sound</h2><p>Load Progress resumes the expedition saved on this device. New Game replaces the current expedition; completed local scores and sound settings remain. Settings lets you adjust music and effects or return to the main menu. This release has local scores and no online account or developer-operated cloud sync. Device backups are controlled by Apple and your settings.</p>\\n<h2>Contact support</h2><p>Email support@ideaspike.com with the app version, device, iOS version and a short description of the problem. Do not send passwords, full payment details or unnecessary personal information. TestFlight transactions use Apple’s sandbox and do not charge real money.</p>"},"terms":{"title":"Terms of Use","body":"<h2>Game and educational content</h2><p>Understone combines public clues, resource planning and gemstone collection. Mineral descriptions and references support learning; game costs, rarity, values and map distributions are game rules and are not real-world mineral prices, mining instructions or safety advice. Educational descriptions can contain inaccuracies or simplifications; verify important real-world information independently.</p>\\n<h2>Trial and full access</h2><p>The opening district’s three floors and first camp are free to play. Continuing beyond that camp requires the one-time non-consumable full-game unlock through Apple. The full expedition spans eight districts and 24 floors; this is not a subscription. Apple displays the applicable offer and price and handles payment. Restore Purchases checks the eligible Apple Account’s valid entitlement; a pending, refunded or revoked transaction does not itself guarantee access. A price or currency change may require review of the new offer. TestFlight purchase testing uses Apple’s sandbox and does not charge real money. Refund requests follow Apple’s process and applicable law; mandatory consumer rights remain available.</p>\\n<h2>Local progress and retries</h2><p>Failure can roll back the current floor attempt to its entry state and generate a new map. Replacement expeditions and deleted saves may not be recoverable. Keep device access secure and consider your backup settings. Restoring an entitlement does not recreate local progress.</p>\\n<h2>Licence and intellectual property</h2><p>For App Store downloads, Apple’s Standard EULA governs the app licence unless a custom EULA is provided for your country or region through App Store Connect. These Terms supplement the applicable EULA and govern IDEASpike accounts, online services, app content and paid entitlements, where offered. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the game for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design, artwork, music and supplied content, subject to identified third-party licences.</p>\\n<h2>Responsible use</h2><p>Use the game lawfully, respect its content licenses and do not interfere with its operation or purchase verification. Learning and play outcomes are not guaranteed. Features depend on supported devices and Apple services.</p>\\n<h2>Availability and your rights</h2><p>IDEASpike may update, suspend or discontinue features. To the extent permitted by law, the game is provided as available without additional warranties beyond those expressly stated in these terms or required by law, and IDEASpike is not liable for indirect or consequential loss arising from local-progress loss, interruption or reliance on educational content. Nothing in these terms excludes liability or consumer rights that cannot be excluded under applicable law. Updated terms appear here. Contact support@ideaspike.com for assistance.</p>"}},"zh-Hans":{"labels":{"updated":"更新日期：2026年10月12日","operator":"Understone 由 IDEASpike 提供。联系："},"privacy":{"title":"隐私政策","body":"<h2>应用与数据</h2><p>Understone 是矿物推理游戏，无需应用账户。我们不会将游戏过程、进度、本地成绩或声音设置收集或发送到 IDEASpike 服务器。应用不含广告、跟踪或第三方分析服务。</p>\\n<h2>设备上的信息</h2><p>当前探险、已发现标本、已完成的本地成绩和声音设置保存在应用的本地存储中。“新游戏”替换当前探险，并保留完成成绩和声音设置。删除应用会删除其本地应用数据；Apple 管理的设备备份中可能仍有副本。应用不提供跨设备同步。IDEASpike 无法远程恢复或删除这些本地文件及设备备份；备份是否可用及能否恢复取决于你的 Apple 或设备设置。</p>\\n<h2>Apple 购买</h2><p>一次性完整探险购买由 Apple 处理。应用通过 StoreKit 接收商品、商店地区和已验证交易信息，用于显示当地价格、检查解锁状态和恢复购买。我们不会获得付款卡资料或 Apple 账户密码，应用也不会将交易信息发送至 IDEASpike 服务器。Apple 的购买处理适用其自身隐私条款。</p>\\n<h2>可选外部链接</h2><p>仅在你主动选择时，地质研究、音乐鸣谢、支持和隐私链接才会打开外部网页。这些网站和浏览器可能按各自的隐私政策处理信息。打开链接不会自动上传你的探险数据。</p>\\n<h2>选择与问题</h2><p>你可以不购买而体验第一个矿区，也可调整声音、替换当前探险或移除应用。购买和退款由 Apple 管理。隐私问题可发送至 support@ideaspike.com；你主动提供的支持邮件信息仅用于回复请求。请勿包含密码或付款卡资料。适用的隐私权利仍然有效。</p>\\n<h2>政策更新</h2><p>本政策描述当前版本。若应用的数据处理方式变化，我们会更新此政策。</p>"},"support":{"title":"应用支持","body":"<h2>规划每次采集</h2><p>点击未探索的格子进行探索。打开宝石格时立即扣除采集所需精力，再点一次可免费收集宝石并获得经验。空格和提示数字不消耗精力；数字表示周围八个格子的采集消耗总和。红色警示标记的数量表示周围地雷的数量。</p>\\n<h2>恢复精力，继续探险</h2><p>精力可以降到零。在需要恢复时吃已发现的汉堡，可以补满精力；经验足够时也可手动升级。失败后重试会生成新地图，并恢复当前小关进入时的状态。新游戏和游戏内帮助页面都提供交互式练习导览。</p>\\n<h2>免费开局与完整探险</h2><p>第一个矿区包含三个免费小关和营地商店。离开第一个营地时，可通过一次性购买“解锁全部矿区”继续后续探险。完整探险包含八个矿区、24个小关，无需订阅。Apple 按你的 App Store 地区显示当地货币价格。营地商品使用游戏中获得的金币购买。</p>\\n<h2>购买与恢复</h2><p>购买由 Apple 处理。在解锁页面使用“恢复购买”，并登录符合条件的 Apple 账户。恢复购买验证完整游戏权益，不会恢复已删除的探险。等待批准的购买仅在有效 Apple 交易通过验证后解锁；取消购买会保留进度。金额或币种改变时，请先查看新报价再确认。价格或购买不可用时，请检查网络后重试，仍有问题可联系我们。请勿重复购买来解决已有交易问题。退款可在 reportaproblem.apple.com 申请，是否符合条件取决于 Apple 政策和适用法律。</p>\\n<h2>进度与声音</h2><p>“读取进度”继续本设备上的存档。“新游戏”替换当前探险，但保留已完成的本地成绩和声音设置。设置可调整音乐、音效或返回主界面。本版本使用本地成绩，无应用账户或开发者提供的云同步。设备备份由 Apple 和你的系统设置管理。</p>\\n<h2>联系支持</h2><p>请发送邮件至 support@ideaspike.com，说明应用版本、设备、iOS 版本和问题。请勿发送密码、完整付款资料或不必要的个人信息。TestFlight 交易使用 Apple 沙盒，不会产生真实扣款。</p>"}},"zh-Hant":{"labels":{"updated":"更新日期：2026年10月12日","operator":"Understone 由 IDEASpike 提供。聯絡："},"privacy":{"title":"隱私政策","body":"<h2>應用與資料</h2><p>Understone 是礦物推理遊戲，無需應用帳號。我們不會將遊戲過程、進度、本機成績或聲音設定收集或傳送到 IDEASpike 伺服器。應用不含廣告、追蹤或第三方分析服務。</p>\\n<h2>裝置上的資訊</h2><p>目前探險、已發現標本、已完成的本機成績和聲音設定保存在應用的本機儲存中。「新遊戲」替換目前探險，並保留完成成績和聲音設定。刪除應用會刪除其本機應用資料；Apple 管理的裝置備份中可能仍有副本。應用不提供跨裝置同步。IDEASpike 無法遠端復原或刪除這些本機檔案及裝置備份；備份是否可用及能否復原取決於你的 Apple 或裝置設定。</p>\\n<h2>Apple 購買</h2><p>一次性完整探險購買由 Apple 處理。應用透過 StoreKit 接收商品、商店地區和已驗證交易資訊，用於顯示當地價格、檢查解鎖狀態和恢復購買。我們不會取得付款卡資料或 Apple 帳號密碼，應用也不會將交易資訊傳送至 IDEASpike 伺服器。Apple 的購買處理適用其自身隱私條款。</p>\\n<h2>可選外部連結</h2><p>僅在你主動選擇時，地質研究、音樂鳴謝、支援和隱私連結才會打開外部網頁。這些網站和瀏覽器可能按各自的隱私政策處理資訊。打開連結不會自動上傳你的探險資料。</p>\\n<h2>選擇與問題</h2><p>你可以不購買而體驗第一個礦區，也可調整聲音、替換目前探險或移除應用。購買和退款由 Apple 管理。隱私問題可傳送至 support@ideaspike.com；你主動提供的支援郵件資訊僅用於回覆請求。請勿包含密碼或付款卡資料。適用的隱私權利仍然有效。</p>\\n<h2>政策更新</h2><p>本政策描述目前版本。若應用的資料處理方式變化，我們會更新此政策。</p>"},"support":{"title":"應用程式支援","body":"<h2>規劃每次採集</h2><p>點擊未探索的格子進行探索。打開寶石格時立即扣除採集所需精力，再點一次可免費收集寶石並獲得經驗。空格和提示數字不消耗精力；數字表示周圍八個格子的採集消耗總和。紅色警示標記的數量表示周圍地雷的數量。</p>\\n<h2>恢復精力，繼續探險</h2><p>精力可以降到零。在需要恢復時吃已發現的漢堡，可以補滿精力；經驗足夠時也可手動升級。失敗後重試會產生新地圖，並恢復目前小關進入時的狀態。新遊戲和遊戲內說明頁面都提供互動式練習導覽。</p>\\n<h2>免費開局與完整探險</h2><p>第一個礦區包含三個免費小關和營地商店。離開第一個營地時，可透過一次性購買「解鎖全部礦區」繼續後續探險。完整探險包含八個礦區、24個小關，無需訂閱。Apple 按你的 App Store 地區顯示當地貨幣價格。營地商品使用遊戲中獲得的金幣購買。</p>\\n<h2>購買與恢復</h2><p>購買由 Apple 處理。在解鎖頁面使用「恢復購買」，並登入符合條件的 Apple 帳號。恢復購買驗證完整遊戲權益，不會復原已刪除的探險。等待批准的購買僅在有效 Apple 交易通過驗證後解鎖；取消購買會保留進度。金額或幣別改變時，請先查看新報價再確認。價格或購買不可用時，請檢查網路後重試，仍有問題可聯絡我們。請勿重複購買來解決已有交易問題。退款可在 reportaproblem.apple.com 申請，是否符合條件取決於 Apple 政策和適用法律。</p>\\n<h2>進度與聲音</h2><p>「讀取進度」繼續本裝置上的存檔。「新遊戲」替換目前探險，但保留已完成的本機成績和聲音設定。設定可調整音樂、音效或返回主畫面。本版本使用本機成績，無應用帳號或開發者提供的雲端同步。裝置備份由 Apple 和你的系統設定管理。</p>\\n<h2>聯絡支援</h2><p>請傳送郵件至 support@ideaspike.com，說明應用版本、裝置、iOS 版本和問題。請勿傳送密碼、完整付款資料或不必要的個人資訊。TestFlight 交易使用 Apple 沙盒，不會產生真實扣款。</p>"}}}'),epocharium:JSON.parse('{"en":{"labels":{"updated":"Last updated: October 12, 2026","operator":"Operated by IDEASpike. Contact:"},"privacy":{"title":"Privacy Policy","body":"<h2>The current prototype</h2><p>Epocharium is a museum-building prototype provided by IDEASpike. The cloud-connected iOS prototype uses an online account and AWS services to maintain museum progress. This policy describes the current prototype.</p>\\n<h2>Account and museum information</h2><p>AWS Cognito processes your email address, password and verification or recovery requests for authentication. The service associates an account identifier with your museum layout, collection, resources, progression and action receipts. These records allow the app to load your museum and resolve repeated or interrupted actions. The app keeps session information and pending-action information in device storage protected by iOS. Do not send your password or verification codes to support.</p>\\n<h2>Cloud processing and diagnostics</h2><p>Museum records are stored using AWS. Processing may take place outside your country, including the United States. Service logs are configured for approximately seven days and contain usage and diagnostic information used to operate and troubleshoot the prototype. Account and museum records have a separate retention period. The current museum prototype does not collect photos, audio recordings or location information for museum play.</p>\\n<h2>Retention and your choices</h2><p>Museum and account records remain in the online service while maintained for your account. Signing out or deleting the app does not delete those cloud records. Contact support@ideaspike.com to request access, correction or account deletion. We may verify that you control the account and will confirm the outcome of the request.</p>\\n<h2>Apple and purchases</h2><p>Apple processes App Store and TestFlight interactions under its own terms and privacy practices. The prototype contains simulated game transactions and a StoreKit purchase-testing feature. Simulation is not a real-money purchase. A StoreKit verification result in this prototype does not establish that a production purchase has been fulfilled in your museum. Apple sandbox transactions do not charge real money. We do not receive payment-card details from Apple.</p>\\n<h2>Website and Apple services</h2><p>Opening a website or reference link sends ordinary web-request information, such as an IP address and browser information, to its hosting provider. Feedback you choose to send through TestFlight may be visible to IDEASpike. Information you send to support is used to respond to your request. Do not send passwords, payment details or unnecessary personal information.</p>\\n<h2>Support and policy updates</h2><p>Information you choose to email to support@ideaspike.com is used to address your request. Include only what is needed and omit sensitive account details. You may raise a privacy question or complaint without giving up rights under applicable law. We will update this policy when the relevant data practices change.</p>"},"terms":{"title":"Terms of Use","body":"<h2>Prototype scope</h2><p>Epocharium lets you explore museum layout, exhibits, collections and resource progression. Prototype features and test progress may change or reset during development.</p>\\n<h2>Accounts and responsible use</h2><p>Use an account you are authorized to access, protect your sign-in details and use the prototype lawfully. Do not interfere with other accounts, exploit purchase verification, disrupt the service or use content without the required rights. A parent or guardian must provide any permission required by applicable law for a child’s use.</p>\\n<h2>Museum and educational content</h2><p>Exhibits, descriptions and game values are for play and general learning. They may contain inaccuracies or simplified interpretations. In-game ownership does not transfer ownership of a real exhibit, intellectual-property rights or a real-world asset. Respect the applicable licenses and attribution for supplied content.</p>\\n<h2>Licence and intellectual property</h2><p>For App Store downloads, Apple’s Standard EULA governs the app licence unless a custom EULA is provided for your country or region through App Store Connect. These Terms supplement the applicable EULA and govern IDEASpike accounts, online services, app content and paid entitlements, where offered. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the prototype for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design and supplied content.</p>\\n<h2>Test resources and purchases</h2><p>In-game test resources and simulated transactions have no cash value and are not bank deposits, investments or a promise of redemption. The prototype’s purchase-testing controls must not be treated as a production store. Any future real-money offer must identify what is supplied and the applicable price before purchase. For an Apple transaction, use Apple’s purchase and refund process; refund eligibility also depends on applicable law. Nothing here waives mandatory consumer rights.</p>\\n<h2>Availability and your rights</h2><p>IDEASpike may update, suspend or discontinue prototype features. To the extent permitted by law, the prototype is provided as available without additional warranties beyond those expressly stated in these terms or required by law, and IDEASpike is not liable for indirect or consequential loss arising from test-progress loss, interruption or reliance on prototype content. Nothing in these terms excludes liability or consumer rights that cannot be excluded under applicable law. Updated terms appear here. Contact support@ideaspike.com for assistance.</p>"},"support":{"title":"Support","body":"<h2>Sign in to the cloud prototype</h2><p>Create or sign in to your Epocharium account using your email address. Complete the email-verification step when requested. Use the confirmation-code resend or password-recovery flow if needed. Check your internet connection and the address you entered. Never email your password, recovery code or sign-in token.</p>\\n<h2>Museum progress and interrupted actions</h2><p>The cloud service maintains the museum associated with your signed-in account. If loading or an action fails, reconnect and use the app’s retry or recovery controls before repeating the action. Test progress may be reset during development. Signing out, reinstalling or using a different account does not constitute cloud-account deletion.</p>\\n<h2>Purchase testing</h2><p>Simulated purchases affect test resources only. The separate StoreKit testing feature may show Apple product or verification information, but does not promise production game fulfillment. TestFlight purchase testing uses Apple’s sandbox and does not charge real money. For a real Apple purchase issue, check your purchase history and contact support before attempting another purchase; Apple handles refund requests.</p>\\n<h2>Privacy requests and support</h2><p>Email support@ideaspike.com with the app version, device model, iOS version, the operation that failed and a short description. During private testing you may also use TestFlight feedback. Use the same address for account access, correction or deletion requests. Do not include passwords, sign-in codes, payment-card details or unnecessary personal information.</p>"}}}')},l={privacy:"Privacy Policy",terms:"Terms of Use",support:"Support"},u={privacy:"privacy",terms:"tos",support:"support"};function h(e,t){var a;if("final-curtain"===e)return"support"===t?["en"]:["en","zh-Hans","zh-Hant"];if("owlguard-ai"===e)return["en"];let n=null!=(a=c[e])?a:{};return Object.keys(n).filter(e=>{var a;return null==(a=n[e])?void 0:a[t]})}function m(e,t){var a;let n=arguments.length>2&&void 0!==arguments[2]?arguments[2]:"en";if("final-curtain"===e){if("support"===t)return i;let e=r[n];return{title:"privacy"===t?e.privacyTitle:e.termsTitle,updated:e.updated,sections:e[t].map(e=>{let[t,a]=e;return{title:t,paragraphs:[a]}})}}if("owlguard-ai"===e)return{...s[t],updated:s.updated};let o=c[e];if(!o)throw Error("Unknown application: ".concat(e));let p=(null==(a=o[n])?void 0:a[t])?o[n]:o.en,d=p[t];if(!d)throw Error("Missing ".concat(t," document for ").concat(e));return{...d,updated:p.labels.updated}}},7995:e=>{e.exports=JSON.parse('{"en":{"updated":"Updated October 12, 2026","privacyTitle":"Privacy Policy","termsTitle":"Terms of Service","contact":"Contact","privacy":[["What Final Curtain does","Final Curtain is a local time-reflection app. It estimates remaining time from a birth date and a horizon you choose, and lets you explore recurring activities, large time blocks, reserves and separate profiles. It does not predict lifespan."],["Information on your device","Birth dates, profile names, chosen horizons, activity names and amounts, retirement or graduation assumptions, and block/reserve settings are stored on the current device. The selected horizon is shared locally with the widget through an Apple App Group. The app has no separate app account, custom backend or app-provided cloud synchronization."],["Optional on-device AI","On supported devices with Apple Intelligence enabled, a summary can use Apple’s on-device Foundation Models. Allocation data is processed on the device and is not sent to IDEASpike or a cloud AI provider. Generated text can be incomplete or inaccurate and is not a diagnosis or prediction."],["Apple purchases and services","Apple processes the optional Final Curtain Pro purchase. StoreKit provides product and purchase-entitlement information so the app can unlock Pro and recognize an eligible legacy widget purchase; we do not receive payment-card details. Apple’s App Store, TestFlight and device services operate under Apple’s own policies. Feedback that you voluntarily send through TestFlight may be visible to IDEASpike."],["Storage and your choices","You can remove activities, clear a list, edit assumptions and delete additional profiles in the app. At least one profile remains. Removing the app removes its app-local files; device backups may retain copies according to your Apple/device backup settings. We do not provide cross-device recovery or remote deletion of your backups."],["Website and contact","Opening legal or reference links contacts the destination website. Hosting providers receive ordinary web-request information such as IP addresses. Information you choose to email to support is used to respond to your request. The app does not include advertising or developer-added tracking/analytics SDKs."],["Changes and assistance","We update this page when processing changes. For questions or assistance, contact support@ideaspike.com. This policy applies to Final Curtain; other IDEASpike apps have their own policies."]],"terms":[["Purpose and estimates","Final Curtain helps you reflect on finite time and compare choices. Birth date, life horizon, rates, block durations and end dates are assumptions you control. Estimates are not predictions, commitments or guarantees that you will complete any activity."],["Your choices","You decide what matters, whether to change an allocation, and whether to follow any suggestion. Example amounts and population averages are not personal targets. Large blocks replace routine time from today; needs inside those periods are included. References explain comparisons, not an optimal life plan."],["AI and health","Optional on-device summaries can be incomplete or inaccurate. The app does not provide medical, financial or other professional advice, diagnose a person, or determine their worth. For sleep or health concerns, consult an appropriate professional rather than relying on allocation arithmetic."],["Purchases","Final Curtain Pro unlocks Compare Choices and the Home Screen widget through a one-time non-consumable Apple purchase, rather than a subscription. An eligible verified legacy widget purchase also grants Pro access. Apple displays the current offer and price and handles payment. Restoration depends on the applicable Apple Account and a valid StoreKit entitlement; refunded or revoked entitlements may no longer unlock Pro. Restoring a purchase does not restore deleted local planning data. Refund requests follow Apple’s process and applicable law; these terms do not limit mandatory consumer rights."],["Local data","Keep device access secure and consider your backup settings. Profiles stay on the current device and are not app accounts. Single-activity deletion occurs immediately, including a full swipe; clearing the list and deleting a profile require confirmation. We do not guarantee recovery of removed local data."],["Licence and intellectual property","For App Store downloads, Apple’s Standard EULA governs the app licence unless a custom EULA is provided for your country or region through App Store Connect. These Terms supplement the applicable EULA and govern IDEASpike accounts, online services, app content and paid entitlements, where offered. Subject to that agreement and these terms, IDEASpike grants you a limited, personal and non-transferable licence to use the app for its intended purpose. IDEASpike and its licensors retain all rights in the app, software, design and supplied content."],["Use and availability","Use the app lawfully and respect other people’s privacy when entering their information. IDEASpike may update, suspend or discontinue features. To the extent permitted by law, the app is provided as available without additional warranties beyond those expressly stated in these terms or required by law, and IDEASpike is not liable for indirect or consequential loss arising from reliance on estimates, generated reflections or service interruption. Nothing in these terms excludes liability or consumer rights that cannot be excluded under applicable law."],["Updates and contact","Updated terms appear on this page. Contact support@ideaspike.com for app questions or purchase assistance."]]},"zh-Hans":{"updated":"更新于 2026 年 10 月 12 日","privacyTitle":"隐私政策","termsTitle":"使用条款","contact":"联系","privacy":[["应用提供什么","Final Curtain 是本地时间反思应用。它依据生日和你选择的人生期限估算剩余时间，帮助你探索日常活动、大块时间、预留余量及不同档案。它不会预测寿命。"],["本设备上的信息","生日、档案名称、人生期限、活动名称和时间量、退休或毕业假设及大块时间与预留设置保存在当前设备。所选期限通过 Apple App Group 在本设备与小组件共享。应用没有独立登录账户、自建后台或应用提供的云同步。"],["可选的设备端 AI","在支持 Apple Intelligence 且已启用的设备上，总结可使用 Apple 设备端 Foundation Models。活动分配数据只在设备上处理，不会发送给 IDEASpike 或云端 AI 服务商。生成内容可能不完整或不准确，不是诊断或预测。"],["Apple 购买与服务","Apple 处理可选的 Final Curtain Pro 购买。StoreKit 提供商品与购买权益信息，供应用解锁 Pro 并识别符合条件的旧版小组件购买；我们不接收银行卡资料。App Store、TestFlight 和设备服务适用 Apple 自己的政策。你主动通过 TestFlight 发送的反馈可能由 IDEASpike 查看。"],["保存期限与选择","你可删除活动、清空清单、修改假设及删除多余档案。至少保留一个档案。删除应用会删除其本地文件；Apple 或设备备份可能依照你的备份设置保留副本。我们不提供跨设备恢复，也不能远程删除你的备份。"],["网站与联系","打开法律或参考链接会连接到目标网站，托管服务会收到 IP 地址等常规请求信息。你主动发送给支持邮箱的信息用于回复请求。应用不包含广告或开发者添加的跟踪、分析 SDK。"],["更新与协助","处理方式改变时会更新本页。有问题可联系 support@ideaspike.com。本政策适用于 Final Curtain，其他 IDEASpike 应用有各自政策。"]],"terms":[["用途与估算","Final Curtain 帮助你认识有限时间并比较选择。生日、人生期限、时间量、大块活动时长和结束期限均是你控制的假设。结果不是预测、承诺或完成活动的保证。"],["你的选择","什么重要、是否调整时间及是否采纳建议，均由你决定。示例数值和群体平均值不是个人目标。大块时间从今天起替代日常时间，期间的生活需要已包含在内。参考资料用于解释比较，并不代表最优人生方案。"],["AI 与健康","可选的设备端总结可能不完整或不准确。应用不提供医疗、财务等专业建议，不诊断个人，也不衡量个人价值。睡眠或健康问题应咨询相应专业人士，而非依赖时间分配计算。"],["购买","Final Curtain Pro 通过 Apple 的一次性非消耗型购买解锁“比较选择”和主屏幕小组件，无需订阅。符合条件且已验证的旧版小组件购买也可获得 Pro 权益。Apple 显示当前商品与价格并处理付款。恢复购买依赖相应 Apple 账户及有效的 StoreKit 权益；已退款或撤销的权益可能不再解锁 Pro。恢复购买不会恢复已删除的本地规划数据。退款遵循 Apple 流程和适用法律；这些条款不限制强制性消费者权利。"],["本地数据","请保护设备访问安全并了解备份设置。档案只保存在当前设备，不是应用账户。单项活动会立即删除，包括完整左滑；清空清单和删除档案仍需确认。我们不保证恢复已删除的本地数据。"],["许可与知识产权","通过 App Store 下载的应用，除非 App Store Connect 已为你所在国家或地区指定自定义最终用户许可协议，否则其应用许可受 Apple 标准最终用户许可协议约束。本条款补充适用的许可协议，并规范 IDEASpike 提供的账户、在线服务、应用内容和付费权益（如有）。在该协议和本条款约束下，IDEASpike 授予你仅为预定用途使用本应用的有限、个人且不可转让许可。应用、软件、设计及所提供内容的全部权利由 IDEASpike 及其许可方保留。"],["使用与可用性","请合法使用应用，录入他人信息时尊重其隐私。IDEASpike 可更新、暂停或停止功能。在法律允许的范围内，应用按可用状态提供，除本条款明确约定或法律要求外，不作出额外保证；对于依赖估算、生成的反思文字或服务中断造成的间接或后果性损失，IDEASpike 不承担责任。本条款不排除依法不得排除的责任或消费者权利。"],["更新与联系","更新条款会在本页发布。应用问题或购买协助可联系 support@ideaspike.com。"]]},"zh-Hant":{"updated":"更新於 2026 年 10 月 12 日","privacyTitle":"隱私政策","termsTitle":"使用條款","contact":"聯絡","privacy":[["App 提供什麼","Final Curtain 是本機時間反思 App。它依據生日和你選擇的人生期限估算剩餘時間，協助你探索日常活動、大段時間、預留餘量及不同檔案。它不會預測壽命。"],["本裝置上的資訊","生日、檔案名稱、人生期限、活動名稱和時間量、退休或畢業假設及大段時間與預留設定保存在目前裝置。所選期限透過 Apple App Group 在本裝置與小工具共享。App 沒有獨立登入帳號、自建後台或 App 提供的雲端同步。"],["可選的裝置端 AI","在支援 Apple Intelligence 且已啟用的裝置上，總結可使用 Apple 裝置端 Foundation Models。活動分配資料只在裝置上處理，不會傳送給 IDEASpike 或雲端 AI 服務商。產生內容可能不完整或不準確，不是診斷或預測。"],["Apple 購買與服務","Apple 處理可選的 Final Curtain Pro 購買。StoreKit 提供商品與購買權益資訊，供 App 解鎖 Pro 並識別符合條件的舊版小工具購買；我們不接收銀行卡資料。App Store、TestFlight 和裝置服務適用 Apple 自己的政策。你主動透過 TestFlight 傳送的回饋可能由 IDEASpike 查看。"],["保存期限與選擇","你可刪除活動、清空清單、修改假設及刪除多餘檔案。至少保留一個檔案。刪除 App 會刪除其本機檔案；Apple 或裝置備份可能依照你的備份設定保留副本。我們不提供跨裝置復原，也不能遠端刪除你的備份。"],["網站與聯絡","開啟法律或參考連結會連接目標網站，託管服務會收到 IP 位址等一般請求資訊。你主動傳送給支援信箱的資訊用於回覆請求。App 不包含廣告或開發者新增的追蹤、分析 SDK。"],["更新與協助","處理方式改變時會更新本頁。有問題可聯絡 support@ideaspike.com。本政策適用於 Final Curtain，其他 IDEASpike App 有各自政策。"]],"terms":[["用途與估算","Final Curtain 協助你認識有限時間並比較選擇。生日、人生期限、時間量、大段活動時長和結束期限均是你控制的假設。結果不是預測、承諾或完成活動的保證。"],["你的選擇","什麼重要、是否調整時間及是否採納建議，均由你決定。範例數值和群體平均值不是個人目標。大段時間從今天起取代日常時間，期間的生活需要已包含在內。參考資料用於解釋比較，並不代表最優人生方案。"],["AI 與健康","可選的裝置端總結可能不完整或不準確。App 不提供醫療、財務等專業建議，不診斷個人，也不衡量個人價值。睡眠或健康問題應諮詢相應專業人士，而非依賴時間分配計算。"],["購買","Final Curtain Pro 透過 Apple 的一次性非消耗型購買解鎖「比較選擇」和主畫面小工具，無需訂閱。符合條件且已驗證的舊版小工具購買也可取得 Pro 權益。Apple 顯示目前商品與價格並處理付款。復原購買依賴相應 Apple 帳號及有效的 StoreKit 權益；已退款或撤銷的權益可能不再解鎖 Pro。復原購買不會復原已刪除的本機規劃資料。退款遵循 Apple 流程和適用法律；這些條款不限制強制性消費者權利。"],["本機資料","請保護裝置存取安全並了解備份設定。檔案只保存在目前裝置，不是 App 帳號。單項活動會立即刪除，包括完整左滑；清空清單和刪除檔案仍需確認。我們不保證復原已刪除的本機資料。"],["授權與智慧財產權","透過 App Store 下載的 App，除非 App Store Connect 已為你所在國家或地區指定自訂最終使用者授權協議，否則其 App 授權受 Apple 標準最終使用者授權協議約束。本條款補充適用的授權協議，並規範 IDEASpike 提供的帳號、線上服務、App 內容及付費權益（如有）。在該協議及本條款約束下，IDEASpike 授予你僅為預定用途使用本 App 的有限、個人且不可轉讓授權。App、軟體、設計及所提供內容的全部權利由 IDEASpike 及其授權方保留。"],["使用與可用性","請合法使用 App，輸入他人資訊時尊重其隱私。IDEASpike 可更新、暫停或停止功能。在法律允許的範圍內，App 按可用狀態提供，除本條款明確約定或法律要求外，不作出額外保證；對於依賴估算、產生的反思文字或服務中斷造成的間接或後果性損失，IDEASpike 不承擔責任。本條款不排除依法不得排除的責任或消費者權利。"],["更新與聯絡","更新條款會在本頁發布。App 問題或購買協助可聯絡 support@ideaspike.com。"]]}}')}}]);